def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = float(my_status.get('no_water_days', 0.0))

    # Base target: slightly below observed strong bidders to avoid price war.
    # If yesterday had extreme bids, we must ensure we get water.
    # Supply affects how many total units are feasible; keep bids within plausible range.
    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Determine aggression
    extreme = highest_prev_bid >= (DAILY_SALARY * 0.85)

    if my_hp <= 2.0 or no_water_days >= 2.0:
        # Critical: bid close to salary to secure allocation.
        target = DAILY_SALARY * (0.85 if extreme else 0.75)
    elif extreme:
        # Others are overpaying; still bid enough but undercut.
        target = min(avg_prev_bid * 0.85, DAILY_SALARY * 0.75 + 10.0)
    else:
        # Normal: bid moderately; ramp with supply.
        target = (DAILY_SALARY * 0.55) + (DAILY_SALARY * 0.15 * supply_factor)

    # Ensure non-negative and budget-capped
    target = max(0.0, target)
    bid = min(my_budget, target)

    # If budget is very low, bid what we can.
    if my_budget <= 1.0:
        return float(my_budget)

    return float(bid)

